/**
 * Manim-web autocomplete for CodeMirror 6.
 *
 * Provides context-aware completions for the manim-web API:
 *  - Global symbol completion (all manim-web exports)
 *  - Import completion (after `import { `)
 *  - Constructor completion (after `new `, classes only)
 *  - Member completion (after `obj.`, based on inferred type)
 *
 * Completion data is generated by scripts/generate-completions.mjs from
 * manim-web's .d.ts files — no hand-maintained lists.
 */

import { Completion, CompletionContext, CompletionResult } from '@codemirror/autocomplete';
import { syntaxTree } from '@codemirror/language';
import { SyntaxNode } from '@lezer/common';
import type { EditorView } from '@codemirror/view';
import { manimWebCompletions } from './generated-completions';

// Build lookup maps from generated data
const completionsByLabel = new Map<string, Completion>();
for (const c of manimWebCompletions) {
	completionsByLabel.set(c.label, c);
}

const classLabels = new Set<string>();
for (const c of manimWebCompletions) {
	if (c.type === 'class') classLabels.add(c.label);
}

// Known manim-web mobject classes and their members (for member completion)
// These are the most commonly used mobject methods — the rest are covered
// by global symbol completion.
const MEMBER_MAP: Record<string, string[]> = {
	Scene: [
		'add', 'remove', 'play', 'wait', 'render', 'clear', 'setCameraOrientation',
		'beginAmbientCameraRotation', 'stopAmbientCameraRotation',
	],
	ThreeDScene: [
		'add', 'remove', 'play', 'wait', 'render', 'clear', 'setCameraOrientation',
		'beginAmbientCameraRotation', 'stopAmbientCameraRotation', 'setOrbitControlsEnabled',
	],
	Mobject: [
		'shift', 'scale', 'rotate', 'setFill', 'setStroke', 'setOpacity',
		'moveTo', 'nextTo', 'alignTo', 'to_edge', 'to_corner',
	],
	VMobject: [
		'shift', 'scale', 'rotate', 'setFill', 'setStroke', 'setOpacity',
		'moveTo', 'nextTo', 'alignTo', 'to_edge', 'to_corner',
	],
	Sphere: ['shift', 'scale', 'rotate', 'setFill', 'setStroke', 'setOpacity'],
	Circle: ['shift', 'scale', 'rotate', 'setFill', 'setStroke', 'setOpacity'],
	Cube: ['shift', 'scale', 'rotate', 'setFill', 'setStroke', 'setOpacity'],
	ThreeDAxes: ['shift', 'scale', 'rotate'],
	Text: ['shift', 'scale', 'rotate', 'setFill', 'setStroke', 'setOpacity'],
	MathTex: ['shift', 'scale', 'rotate', 'setFill', 'setStroke', 'setOpacity'],
};

/** Get the manim-web type of a variable by tracking assignments in the document. */
function inferVariableType(view: EditorView, varName: string): string | null {
	const doc = view.state.doc;
	const tree = syntaxTree(view.state);

	let bestType: string | null = null;

	// Walk the tree looking for `const x = new ClassName(...)` or `let x = ...`
	const walk = (node: SyntaxNode) => {
		if (node.type.name === 'VariableDeclaration') {
			const nameNode = node.getChild('name');
			if (nameNode && view.state.doc.sliceString(nameNode.from, nameNode.to) === varName) {
				// Look for `new ClassName(` in the initializer
				const init = node.getChild('initializer');
				if (init) {
					const initText = view.state.doc.sliceString(init.from, init.to);
					const newMatch = initText.match(/new\s+(\w+)\s*\(/);
					if (newMatch && newMatch[1]) {
						bestType = newMatch[1];
					}
				}
			}
		}
		let child = node.firstChild;
		while (child) {
			walk(child);
			child = child.nextSibling;
		}
	};

	let cursor = tree.cursor();
	do {
		walk(cursor.node);
	} while (cursor.next());

	return bestType;
}

/** Extract the text of the word/identifier before the cursor. */
function wordBefore(context: CompletionContext): { from: number; text: string } | null {
	const { state, pos } = context;
	const line = state.doc.lineAt(pos);
	const start = Math.max(line.from, pos - 100);
	const text = state.doc.sliceString(start, pos);
	const match = text.match(/([\w$.]*)$/);
	if (!match || !match[1]) return null;
	return { from: start + (match.index ?? 0), text: match[1] };
}

export function manimWebCompletionSource(context: CompletionContext): CompletionResult | null {
	const { state, pos, explicit } = context;

	// Don't trigger on every keystroke unless explicitly activated
	const word = wordBefore(context);
	if (!word) return null;
	if (!explicit && word.text.length < 1) return null;

	const { from, text } = word;

	// --- Context 1: After `new ` → suggest classes only ---
	const beforeText = state.doc.sliceString(Math.max(0, from - 10), from);
	if (/\bnew\s+$/.test(beforeText)) {
		const options: Completion[] = [];
		for (const label of classLabels) {
			const c = completionsByLabel.get(label)!;
			options.push({
				label: c.label,
				type: 'class',
				detail: c.detail,
			});
		}
		return { from, options };
	}

	// --- Context 2: After `obj.` → member completion ---
	const memberMatch = text.match(/^(\w+)\.(\w*)$/);
	if (memberMatch) {
		const varName = memberMatch[1]!;
		const memberPrefix = memberMatch[2] ?? '';
		const varType = context.view ? inferVariableType(context.view, varName) : null;
		const members = varType ? MEMBER_MAP[varType] : null;

		const options: Completion[] = [];
		if (members) {
			for (const m of members) {
				if (!memberPrefix || m.startsWith(memberPrefix)) {
					options.push({
						label: m,
						type: 'method',
						detail: `method of ${varType}`,
					});
				}
			}
		}
		if (options.length > 0) {
			return { from: from + (varName ?? '').length + 1, options };
		}
		return null;
	}

	// --- Context 3: Inside `import { ` → named imports ---
	const importContext = state.doc.sliceString(Math.max(0, from - 30), from);
	if (/\bimport\s*\{\s*$/.test(beforeText) || /\bimport\s*\{\s*[^}]*\s*,\s*$/.test(beforeText)) {
		const options: Completion[] = [];
		for (const c of manimWebCompletions) {
			options.push({
				label: c.label,
				type: c.type,
				detail: c.detail,
			});
		}
		return { from, options };
	}

	// --- Context 4: Global symbol completion ---
	// Only show if there's a partial match or explicit activation
	const input = text;
	const options: Completion[] = [];

	for (const c of manimWebCompletions) {
		// Simple prefix match
		if (c.label.toLowerCase().startsWith(input.toLowerCase())) {
			options.push({
				label: c.label,
				type: c.type,
				detail: c.detail,
			});
		}
	}

	if (options.length === 0 && !explicit) return null;

	return { from, options };
}
